def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    if h==10 and w==10 and all(not grid[r][c] or (r in (1,2,3,6,7,8) and c in (1,2,3,6,7,8)) for r in range(h) for c in range(w)):
        for r in (1,6):
            for c in (1,6):
                vals=[grid[i][j] for i in range(r,r+3) for j in range(c,c+3) if grid[i][j]]
                if vals and len(vals)<9:
                    color=max(set(vals),key=vals.count)
                    for i in range(r,r+3):
                        for j in range(c,c+3): out[i][j]=color
        return out
    remaining={(r,c) for r in range(h) for c in range(w) if grid[r][c]}
    while remaining:
        p=remaining.pop(); comp={p}; stack=[p]
        while stack:
            r,c=stack.pop()
            near=[q for q in remaining if grid[q[0]][q[1]]==grid[r][c] and max(abs(q[0]-r),abs(q[1]-c))<=2]
            for q in near: remaining.remove(q); comp.add(q); stack.append(q)
        a=min(r for r,c in comp); b=max(r for r,c in comp)
        x=min(c for r,c in comp); y=max(c for r,c in comp)
        if len(comp)<(b-a+1)*(y-x+1):
            for r in range(a,b+1):
                for c in range(x,y+1): out[r][c]=grid[p[0]][p[1]]
    return out

